/**
 * Workspace demo — functional test bed (segments 1–3).
 *
 * The views are deliberately real enough to prove the system: their state
 * lives in useViewWorkingState (keyed by view id), so an editor keeps its text and
 * a calculator keeps its display when the view floats, docks, splits, or
 * moves between tabs.
 */

import * as React from "react";

import { GripVertical } from "lucide-react";

import { Button } from "@/registry/ui/button";
import { WorkspaceProvider } from "@/registry/hooks/use-workspace";
import {
  useWorkspaceConfig,
  useWorkspaceDispatch,
  useWorkspaceState,
  useWorkspaceStore,
  type WorkspaceViewProps,
} from "@/registry/hooks/use-workspace";
import { useViewWorkingState } from "@/registry/hooks/use-view-working-state";
import { requestPopout } from "@/registry/blocks/workspace/workspace-popouts";
import {
  deserializeWorkspaceState,
  serializeWorkspaceState,
} from "@/registry/lib/workspace/persistence";
import { WorkspaceTiled } from "@/registry/blocks/workspace/workspace-tiled";
import { WorkspaceFloating } from "@/registry/blocks/workspace/workspace-floating";
import { createInitialState } from "@/registry/lib/workspace/factory";
import type { ModifierKey } from "@/registry/lib/workspace/keymap";

const initialLayout = createInitialState({
  direction: "horizontal",
  ratio: 0.6,
  first: {
    views: [{ type: "editor", title: "Editor" }],
  },
  second: {
    direction: "vertical",
    ratio: 0.55,
    first: {
      views: [
        { type: "calculator", title: "Calculator" },
        { type: "clock", title: "Clock" },
      ],
    },
    second: { views: [{ type: "files", title: "Files" }] },
  },
});

const demoViews = {
  editor: EditorView,
  calculator: CalculatorView,
  files: FilesView,
  clock: ClockView,
};

export function WorkspaceDemo() {
  const [chrome, setChrome] = React.useState<"frame" | "frameless">("frame");
  const [dragModifier, setDragModifier] = React.useState<ModifierKey>("ctrl");
  const [panel, setPanel] = React.useState<"none" | "keys" | "state">("none");

  return (
    <div className="absolute inset-0">
      <WorkspaceProvider
        views={demoViews}
        initialState={initialLayout}
        config={{ floating: { chrome, dragModifier } }}
      >
        <FloatingToolbar
          actions={<ToolbarActions />}
          secondary={
            <>
              <ConfigControls
                chrome={chrome}
                onChromeChange={setChrome}
                dragModifier={dragModifier}
                onDragModifierChange={setDragModifier}
              />
              <Button
                size="sm"
                variant={panel === "keys" ? "secondary" : "ghost"}
                onClick={() => setPanel(panel === "keys" ? "none" : "keys")}
              >
                Keys
              </Button>
              <Button
                size="sm"
                variant={panel === "state" ? "secondary" : "ghost"}
                onClick={() => setPanel(panel === "state" ? "none" : "state")}
              >
                State
              </Button>
              <PersistenceButtons />
            </>
          }
        />
        {panel === "keys" ? <KeysPanel /> : null}
        {panel === "state" ? <StateInspector /> : null}
        <WorkspaceTiled />
        <WorkspaceFloating />
        <StatusBar />
      </WorkspaceProvider>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Toolbar / panels / status bar
// ---------------------------------------------------------------------------

/**
 * Compact floating toolbar: two rows, draggable by its grip. Starts centered
 * at the top (measured after first paint), then lives wherever you drop it.
 */
function FloatingToolbar({
  actions,
  secondary,
}: {
  actions: React.ReactNode;
  secondary: React.ReactNode;
}) {
  const containerRef = React.useRef<HTMLDivElement | null>(null);
  const barRef = React.useRef<HTMLDivElement | null>(null);
  const [position, setPosition] = React.useState<{
    x: number;
    y: number;
  } | null>(null);
  const drag = React.useRef<{
    startX: number;
    startY: number;
    originX: number;
    originY: number;
  } | null>(null);

  // Measure once so the bar starts centered without knowing its own width.
  React.useLayoutEffect(() => {
    if (position || !containerRef.current || !barRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    setPosition({
      x: Math.max(8, rect.width / 2 - barRef.current.offsetWidth / 2),
      y: 10,
    });
  }, [position]);

  function onGripPointerDown(event: React.PointerEvent<HTMLDivElement>) {
    if (!position) return;
    event.preventDefault();
    drag.current = {
      startX: event.clientX,
      startY: event.clientY,
      originX: position.x,
      originY: position.y,
    };
    event.currentTarget.setPointerCapture(event.pointerId);
  }

  function onGripPointerMove(event: React.PointerEvent<HTMLDivElement>) {
    const state = drag.current;
    if (!state) return;
    setPosition({
      x: state.originX + event.clientX - state.startX,
      y: state.originY + event.clientY - state.startY,
    });
  }

  function onGripPointerUp() {
    drag.current = null;
  }

  return (
    <div ref={containerRef} className="pointer-events-none absolute inset-0">
      <div
        ref={barRef}
        style={
          position
            ? { left: position.x, top: position.y }
            : { visibility: "hidden" }
        }
        className="pointer-events-auto absolute z-[9999] flex items-center gap-1 rounded-md border bg-background/95 p-1 shadow-md"
      >
        <div
          role="button"
          aria-label="Move toolbar"
          tabIndex={0}
          onPointerDown={onGripPointerDown}
          onPointerMove={onGripPointerMove}
          onPointerUp={onGripPointerUp}
          onPointerCancel={onGripPointerUp}
          className="flex h-full cursor-grab touch-none items-center rounded text-muted-foreground/70 hover:bg-accent hover:text-foreground active:cursor-grabbing"
        >
          <GripVertical className="size-3.5" />
        </div>
        <div className="flex flex-col items-start gap-1">
          <div className="flex gap-1">{actions}</div>
          <div className="flex gap-1">{secondary}</div>
        </div>
      </div>
    </div>
  );
}

function ToolbarActions() {
  const dispatch = useWorkspaceDispatch();
  const store = useWorkspaceStore();
  const state = useWorkspaceState();

  function popoutActive() {
    const viewId = state.activeStackId
      ? state.stacks[state.activeStackId]?.activeViewId
      : undefined;
    if (viewId) requestPopout(store, viewId);
  }

  return (
    <>
      <Button
        size="sm"
        variant="ghost"
        onClick={() =>
          dispatch({
            type: "view/open",
            viewType: "editor",
            title: `Editor ${new Date().toLocaleTimeString()}`,
          })
        }
      >
        Open Editor
      </Button>
      <Button
        size="sm"
        variant="ghost"
        onClick={() =>
          dispatch({ type: "view/open", viewType: "files", title: "Files" })
        }
      >
        Open Files
      </Button>
      <Button
        size="sm"
        variant="outline"
        onClick={() =>
          dispatch({
            type: "stack/split",
            direction: "horizontal",
            viewType: "editor",
            title: "Editor",
          })
        }
      >
        Split Right
      </Button>
      <Button
        size="sm"
        variant="ghost"
        onClick={() => store.applyCommand("view/float")}
      >
        Float
      </Button>
      <Button
        size="sm"
        variant="ghost"
        onClick={() => store.applyCommand("view/dock")}
      >
        Dock
      </Button>
      <Button size="sm" variant="ghost" onClick={popoutActive}>
        Popout
      </Button>
    </>
  );
}

const STORAGE_KEY = "edcn-workspace-demo";

function PersistenceButtons() {
  const state = useWorkspaceState();
  const store = useWorkspaceStore();

  return (
    <>
      <Button
        size="sm"
        variant="ghost"
        onClick={() =>
          localStorage.setItem(STORAGE_KEY, serializeWorkspaceState(state))
        }
      >
        Save
      </Button>
      <Button
        size="sm"
        variant="ghost"
        onClick={() => {
          const json = localStorage.getItem(STORAGE_KEY);
          if (!json) return;
          const restored = deserializeWorkspaceState(json);
          if (restored) store.hydrate(restored);
        }}
      >
        Load
      </Button>
      <Button
        size="sm"
        variant="ghost"
        onClick={() => {
          localStorage.removeItem(STORAGE_KEY);
          store.hydrate(initialLayout);
        }}
      >
        Reset
      </Button>
    </>
  );
}

function ConfigControls({
  chrome,
  onChromeChange,
  dragModifier,
  onDragModifierChange,
}: {
  chrome: "frame" | "frameless";
  onChromeChange: (chrome: "frame" | "frameless") => void;
  dragModifier: ModifierKey;
  onDragModifierChange: (modifier: ModifierKey) => void;
}) {
  return (
    <>
      <Button
        size="sm"
        variant={chrome === "frame" ? "secondary" : "ghost"}
        onClick={() =>
          onChromeChange(chrome === "frame" ? "frameless" : "frame")
        }
      >
        {chrome === "frame" ? "Chrome: frame" : "Chrome: frameless"}
      </Button>
      <Button
        size="sm"
        variant="ghost"
        onClick={() =>
          onDragModifierChange(dragModifier === "ctrl" ? "alt" : "ctrl")
        }
      >
        Drag: {dragModifier}
      </Button>
    </>
  );
}

function KeysPanel() {
  const config = useWorkspaceConfig();
  return (
    <div className="absolute top-12 left-1/2 z-[9999] w-96 -translate-x-1/2 rounded-md border bg-background p-3 text-xs shadow-md">
      <p className="mb-2 font-medium">Keyboard (override via config.keymap)</p>
      <ul className="space-y-1 font-mono text-muted-foreground">
        <li>alt+w — close active view</li>
        <li>alt+ArrowDown / alt+ArrowUp — next / previous tab</li>
        <li>alt+f — float active view</li>
        <li>alt+d — dock active view</li>
        <li>alt+p — popout active view into its own browser window</li>
      </ul>
      <p className="mt-3 mb-2 font-medium">Pointer</p>
      <ul className="space-y-1 font-mono text-muted-foreground">
        <li>
          drag divider — resize panes · double-click — reset · arrows — nudge
        </li>
        <li>
          {config.floating.chrome === "frameless"
            ? `hold ${config.floating.dragModifier} + drag — move window from anywhere`
            : "drag title bar to move · ctrl+drag also works anywhere"}
        </li>
        <li>click a floating window — bring to front</li>
      </ul>
      <p className="mt-3 text-muted-foreground">
        Tip: click a tab strip to focus a stack — Open/Split target it.
      </p>
    </div>
  );
}

function StateInspector() {
  const state = useWorkspaceState();
  return (
    <pre className="absolute top-12 left-1/2 z-[9999] max-h-72 w-[28rem] -translate-x-1/2 overflow-auto rounded-md border bg-background p-3 text-left text-xs shadow-md">
      {JSON.stringify(state, null, 2)}
    </pre>
  );
}

function StatusBar() {
  const state = useWorkspaceState();
  const activeStack = state.activeStackId
    ? state.stacks[state.activeStackId]
    : undefined;
  const activeView = activeStack?.activeViewId
    ? state.views[activeStack.activeViewId]
    : undefined;

  return (
    <div className="absolute inset-x-0 bottom-0 z-[9999] flex items-center justify-between border-t bg-background/95 px-3 py-1 text-xs text-muted-foreground">
      <span>
        Active view:{" "}
        <span className="font-mono text-foreground">
          {activeView ? `${activeView.title} · ${activeView.id}` : "none"}
        </span>
      </span>
      <span>
        stacks {Object.keys(state.stacks).length} · views{" "}
        {Object.keys(state.views).length} · floating{" "}
        {Object.keys(state.floating).length}
      </span>
    </div>
  );
}

/** Shows the view's stable id — the same instance follows its window around. */
function ViewBadge({ view }: { view: { id: string } }) {
  return (
    <span className="rounded bg-muted px-1.5 py-0.5 font-mono text-[10px] text-muted-foreground">
      {view.id}
    </span>
  );
}

// ---------------------------------------------------------------------------
// Demo views — each keeps working state in useViewWorkingState, keyed by view id,
// so state survives float / dock / split / tab moves.
// ---------------------------------------------------------------------------

function EditorView({ view }: WorkspaceViewProps) {
  const [text, setText] = useViewWorkingState(
    view.id,
    () => `# ${view.title}\n\nType here, then Float or Dock me.\n`,
  );
  const words = text.trim() ? text.trim().split(/\s+/).length : 0;

  return (
    <div className="flex h-full flex-col">
      <div className="flex items-center justify-between border-b px-2 py-1">
        <ViewBadge view={view} />
        <span className="text-[10px] text-muted-foreground">
          {text.split("\n").length} lines · {words} words
        </span>
      </div>
      <textarea
        value={text}
        onChange={(event) => setText(event.target.value)}
        className="h-full w-full resize-none bg-transparent p-3 font-mono text-sm outline-none"
        spellCheck={false}
      />
    </div>
  );
}

interface CalcState {
  display: string;
  acc: number | null;
  op: string | null;
  fresh: boolean;
}

const CALC_KEYS = [
  ["7", "8", "9", "/"],
  ["4", "5", "6", "*"],
  ["1", "2", "3", "-"],
  ["0", ".", "=", "+"],
] as const;

function applyOp(a: number, b: number, op: string): number {
  switch (op) {
    case "+":
      return a + b;
    case "-":
      return a - b;
    case "*":
      return a * b;
    case "/":
      return b === 0 ? NaN : a / b;
    default:
      return b;
  }
}

function calcPress(state: CalcState, key: string): CalcState {
  if (key === "C") return { display: "0", acc: null, op: null, fresh: true };
  if (key === "=") {
    if (state.op !== null && state.acc !== null) {
      return {
        display: String(applyOp(state.acc, Number(state.display), state.op)),
        acc: null,
        op: null,
        fresh: true,
      };
    }
    return state;
  }
  if (["+", "-", "*", "/"].includes(key)) {
    const current = Number(state.display);
    const acc =
      state.op !== null && state.acc !== null && !state.fresh
        ? applyOp(state.acc, current, state.op)
        : current;
    return { display: String(acc), acc, op: key, fresh: true };
  }
  if (state.fresh) {
    return { ...state, display: key === "." ? "0." : key, fresh: false };
  }
  if (key === "." && state.display.includes(".")) return state;
  return {
    ...state,
    display: state.display === "0" && key !== "." ? key : state.display + key,
  };
}

const INITIAL_CALC: CalcState = {
  display: "0",
  acc: null,
  op: null,
  fresh: true,
};

function CalculatorView({ view }: WorkspaceViewProps) {
  const [calc, setCalc] = useViewWorkingState(
    `calc:${view.id}`,
    () => INITIAL_CALC,
  );

  return (
    <div className="flex h-full flex-col">
      <div className="flex items-center justify-between border-b px-2 py-1">
        <ViewBadge view={view} />
        {calc.op !== null ? (
          <span className="text-[10px] text-muted-foreground">
            pending {calc.op} {calc.acc}
          </span>
        ) : null}
      </div>
      <div className="px-3 py-2 text-right font-mono text-2xl tabular-nums">
        {calc.display}
      </div>
      <div className="grid flex-1 grid-cols-4 gap-1 p-2">
        {CALC_KEYS.flat().map((key) => (
          <Button
            key={key}
            variant={
              ["/", "*", "-", "+", "="].includes(key) ? "secondary" : "outline"
            }
            size="sm"
            className="font-mono"
            onClick={() => setCalc((prev) => calcPress(prev, key))}
          >
            {key}
          </Button>
        ))}
        <Button
          variant="ghost"
          size="sm"
          className="col-span-4 font-mono text-destructive"
          onClick={() => setCalc(INITIAL_CALC)}
        >
          C
        </Button>
      </div>
    </div>
  );
}

const DEMO_FILES = [
  "src/main.tsx",
  "src/registry-preview.tsx",
  "registry/lib/workspace/reducer.ts",
  "registry/lib/workspace/types.ts",
  "package.json",
];

function FilesView({ view }: WorkspaceViewProps) {
  const [selected, setSelected] = useViewWorkingState<string | null>(
    `files:${view.id}`,
    () => null,
  );
  const dispatch = useWorkspaceDispatch();

  return (
    <div className="flex h-full flex-col">
      <div className="flex items-center justify-between border-b px-2 py-1">
        <ViewBadge view={view} />
        <span className="text-[10px] text-muted-foreground">
          click a file to open it
        </span>
      </div>
      <ul className="flex-1 overflow-auto p-1 text-sm">
        {DEMO_FILES.map((file) => (
          <li key={file}>
            <button
              type="button"
              onClick={() => {
                setSelected(file);
                // Opens into the ACTIVE stack — click a tab strip first to
                // choose the target.
                dispatch({
                  type: "view/open",
                  viewType: "editor",
                  title: file,
                });
              }}
              className={
                "w-full truncate rounded px-2 py-1 text-left font-mono text-xs " +
                (selected === file
                  ? "bg-accent text-accent-foreground"
                  : "text-muted-foreground hover:bg-accent/60 hover:text-foreground")
              }
            >
              {file}
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}

function ClockView({ view }: WorkspaceViewProps) {
  const [now, setNow] = React.useState(() => new Date());
  React.useEffect(() => {
    const timer = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  return (
    <div className="flex h-full flex-col items-center justify-center gap-2">
      <span className="text-3xl font-bold tabular-nums">
        {now.toLocaleTimeString()}
      </span>
      <ViewBadge view={view} />
    </div>
  );
}

/**
 * <Workspace> — the full workspace system block.
 *
 * Owns the store (via WorkspaceProvider), resolves the consumer's views map
 * and config, mounts the keymap listener, and renders the surfaces: the
 * tiled tree, floating windows, and popout browser windows.
 *
 * ```tsx
 * <Workspace
 *   views={{ editor: EditorView, calculator: CalculatorView }}
 *   initialState={createInitialState({ ... })}
 *   config={{ floating: { chrome: "frameless", dragModifier: "ctrl" } }}
 * />
 * ```
 */

import { WorkspaceProvider } from "@/registry/hooks/use-workspace";
import type { WorkspaceViewsMap } from "@/registry/hooks/use-workspace";
import { useWorkspaceKeymap } from "@/registry/hooks/use-workspace-keymap";
import { WorkspaceFloating } from "@/registry/blocks/workspace/workspace-floating";
import { WorkspacePopouts } from "@/registry/blocks/workspace/workspace-popouts";
import { WorkspaceTiled } from "@/registry/blocks/workspace/workspace-tiled";
import type { WorkspaceConfigInput } from "@/registry/lib/workspace/config";
import type { WorkspaceState } from "@/registry/lib/workspace/types";

export interface WorkspaceProps {
   views: WorkspaceViewsMap;
   initialState: WorkspaceState;
   config?: WorkspaceConfigInput;
   className?: string;
}

export function Workspace({
   views,
   initialState,
   config,
   className,
}: WorkspaceProps) {
   return (
      <div className={className ?? "absolute inset-0"}>
         <WorkspaceProvider
            views={views}
            initialState={initialState}
            config={config}
         >
            <WorkspaceKeymapListener />
            <WorkspaceTiled />
            <WorkspaceFloating />
            <WorkspacePopouts />
         </WorkspaceProvider>
      </div>
   );
}

/** Hook host: useWorkspaceKeymap registers a window-level listener. */
function WorkspaceKeymapListener() {
   useWorkspaceKeymap();
   return null;
}

/**
 * The main tiled surface: renders the workspace's tiled LayoutNode tree inside a
 * padded container. Floating/popout surfaces (segment 3+) will render
 * alongside this in <Workspace>.
 */

import { useWorkspaceState } from "@/registry/hooks/use-workspace";
import { WorkspaceLayout } from "@/registry/ui/workspace-layout";

export function WorkspaceTiled() {
 return (
  <div className="relative h-full w-full p-1.5">
   <TiledRoot />
  </div>
 );
}

/** Subscribes to the store; re-renders only the recursive layout tree. */
function TiledRoot() {
 const state = useWorkspaceState();
 return <WorkspaceLayout node={state.tiled} />;
}

/**
 * Floating surfaces layer: renders every floating window over the tiled
 * area. Geometry is owned by workspace state; each window hosts the same
 * placement-agnostic WorkspaceStack used in the tiled tree.
 */

import { FloatingWindow } from "@/registry/ui/floating-window";
import { WorkspaceStack } from "@/registry/ui/workspace-stack";
import {
  useWorkspaceConfig,
  useWorkspaceDispatch,
  useWorkspaceState,
} from "@/registry/hooks/use-workspace";

export function WorkspaceFloating() {
  const state = useWorkspaceState();
  const config = useWorkspaceConfig();
  const dispatch = useWorkspaceDispatch();

  const surfaces = Object.values(state.floating);
  if (surfaces.length === 0) return null;

  return (
    <>
      {surfaces.map((surface) => {
        const stack = state.stacks[surface.stackId];
        const activeView = stack?.activeViewId
          ? state.views[stack.activeViewId]
          : undefined;

        return (
          <FloatingWindow
            key={surface.id}
            position={{ x: surface.x, y: surface.y }}
            size={{ width: surface.width, height: surface.height }}
            onPositionChange={(position) =>
              dispatch({
                type: "floating/move",
                surfaceId: surface.id,
                x: position.x,
                y: position.y,
              })
            }
            onSizeChange={(size) =>
              dispatch({
                type: "floating/resize",
                surfaceId: surface.id,
                width: size.width,
                height: size.height,
              })
            }
            chrome={config.floating.chrome === "frame"}
            dragModifier={config.floating.dragModifier}
            zIndex={surface.zIndex}
            title={activeView?.title ?? "Window"}
            onClose={() =>
              dispatch({ type: "floating/close", surfaceId: surface.id })
            }
            onPointerDown={() =>
              dispatch({ type: "floating/focus", surfaceId: surface.id })
            }
            contentClassName="p-0"
          >
            <WorkspaceStack
              stackId={surface.stackId}
              className="h-full w-full rounded-none border-0"
            />
          </FloatingWindow>
        );
      })}
    </>
  );
}

/**
 * Popout surfaces layer — hosts stacks in real browser windows.
 *
 * State owns only serializable facts (PopoutSurface); the live Window
 * handles live in this module. A window is opened synchronously inside the
 * user gesture via requestPopout() (popup blockers), then adopted here; the
 * reconcile effect also opens windows for restored/programmatic surfaces
 * and rolls surfaces back if the browser refuses.
 *
 * The child document gets a second React root rendering a WorkspaceProvider
 * bound to the SAME store instance, so a popout is a live viewport onto the
 * one workspace state — closing it (or its last tab) just edits state.
 *
 * Note: HTML5 drag & drop cannot cross browser windows, so dragging tabs
 * between the main window and popouts is out of scope by design.
 */

import * as React from "react";
import { createRoot, type Root } from "react-dom/client";

import { createId } from "@/registry/lib/workspace/ids";
import {
  DEFAULT_POPOUT_HEIGHT,
  DEFAULT_POPOUT_WIDTH,
} from "@/registry/lib/workspace/model/surface";
import type { WorkspaceStore } from "@/registry/lib/workspace/store";
import {
  WorkspaceProvider,
  useWorkspaceContext,
  useWorkspaceDispatch,
  useWorkspaceState,
} from "@/registry/hooks/use-workspace";
import { WorkspaceStack } from "@/registry/ui/workspace-stack";

interface LivePopout {
  win: Window;
  root: Root;
}

/** Windows opened inside the user gesture, awaiting their surface record. */
const pendingWindows = new Map<string, Window>();
/** surfaceId -> live window + React root. */
const livePopouts = new Map<string, LivePopout>();

/**
 * Pop out a view into its own browser window. MUST be called from a user
 * event handler (click) so window.open is not blocked; the window is opened
 * synchronously, then the surface is committed to state.
 */
export function requestPopout(store: WorkspaceStore, viewId: string): void {
  const state = store.getState();
  const view = state.views[viewId];
  if (!view) return;

  const surfaceId = createId("popout");
  const win = window.open(
    "",
    `edcn-popout-${surfaceId}`,
    `popup,width=${DEFAULT_POPOUT_WIDTH},height=${DEFAULT_POPOUT_HEIGHT}`,
  );
  if (!win) return; // popup blocked — nothing is committed to state

  pendingWindows.set(surfaceId, win);
  store.dispatch({
    type: "view/popout",
    surfaceId,
    viewId,
    width: DEFAULT_POPOUT_WIDTH,
    height: DEFAULT_POPOUT_HEIGHT,
  });
}

/** Clone the host document's styles into a popout document. */
function copyStyles(targetDoc: Document): void {
  for (const el of Array.from(
    document.head.querySelectorAll("style, link[rel=stylesheet]"),
  )) {
    targetDoc.head.appendChild(el.cloneNode(true));
  }
}

/**
 * Reconciles state.popouts with live browser windows. Renders nothing in
 * the main window; its effect owns the popout lifecycle.
 */
export function WorkspacePopouts(): null {
  const { store, views, config } = useWorkspaceContext();
  const state = useWorkspaceState();
  const dispatch = useWorkspaceDispatch();
  // Only the set of surface ids should re-run the reconcile effect.
  const surfaceIds = Object.keys(state.popouts).join(",");

  React.useEffect(() => {
    // Close windows whose surface was removed from state (last tab closed,
    // docked, or popout/close).
    for (const [surfaceId, entry] of Array.from(livePopouts)) {
      if (!state.popouts[surfaceId]) {
        entry.root.unmount();
        if (!entry.win.closed) entry.win.close();
        livePopouts.delete(surfaceId);
      }
    }

    // Open windows for surfaces that don't have one yet.
    for (const surface of Object.values(state.popouts)) {
      if (livePopouts.has(surface.id)) continue;

      const win =
        pendingWindows.get(surface.id) ??
        window.open(
          "",
          `edcn-popout-${surface.id}`,
          `popup,width=${surface.width},height=${surface.height}`,
        );
      pendingWindows.delete(surface.id);

      if (!win) {
        // Browser refused (programmatic open outside a gesture) — roll the
        // surface back so state never references a window that can't exist.
        dispatch({ type: "popout/close", surfaceId: surface.id });
        continue;
      }

      const doc = win.document;
      doc.title = "Workspace popout";
      copyStyles(doc);
      const container = doc.createElement("div");
      container.style.cssText = "position:fixed;inset:0;";
      doc.body.appendChild(container);

      const root = createRoot(container);
      root.render(
        React.createElement(
          WorkspaceProvider,
          { store, views, config },
          React.createElement(WorkspaceStack, {
            stackId: surface.stackId,
            className: "h-full w-full rounded-none border-0",
          }),
        ),
      );

      // Closing the OS window closes the surface (and its views).
      win.addEventListener("beforeunload", () => {
        dispatch({ type: "popout/close", surfaceId: surface.id });
      });

      livePopouts.set(surface.id, { win, root });
    }
    // surfaceIds keeps this effect from re-running on unrelated state edits.
  }, [surfaceIds, state.popouts, store, views, config, dispatch]);

  // Close every popout when the host unmounts.
  React.useEffect(() => {
    const entries = Array.from(livePopouts.values());
    return () => {
      for (const entry of entries) {
        entry.root.unmount();
        if (!entry.win.closed) entry.win.close();
      }
      livePopouts.clear();
    };
  }, []);

  return null;
}
